//! The Markdown Card format.
//!
//! A Card's stored text is one Markdown document:
//!
//! ```text
//! # <title>
//!
//! <body Markdown>
//!
//! <!-- zt:reverse-links -->
//! <generated Reverse link section>
//! ```
//!
//! The title is the leading ATX level-one heading. Everything after the
//! Reverse link marker is generated by ZT and replaced on every save; the
//! marker is an HTML comment so that rendered Markdown hides it.

use anyhow::{Result, bail};
use sha2::Digest;

pub(crate) const REVERSE_MARKER: &str = "<!-- zt:reverse-links -->";
pub(crate) const REVERSE_HEADING: &str = "## Reverse links";
const LEGACY_DELIM: &str = "<--->";

#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ParsedCard {
    pub(crate) title: String,
    pub(crate) body: String,
    pub(crate) reverse: String,
}

/// Reject an extra authored title after the legitimate Card envelope. An
/// indented code line is literal code, not another title or claim paragraph.
pub(crate) fn body_starts_with_title(title: &str, body: &str) -> bool {
    body.lines()
        .find(|line| !line.trim().is_empty())
        .is_some_and(|line| {
            !line.starts_with("    ")
                && !line.starts_with('\t')
                && (line.trim() == title
                    || title_from_heading(line.trim()).as_deref() == Some(title))
        })
}
/// Parse a Topic or Regular Card, which must open with a `# Title` heading.
pub(crate) fn parse_card_text(text: &str) -> Result<ParsedCard> {
    parse(text, true)
}

/// Parse edited Literature Card text. Its title comes from BibTeX metadata,
/// so a leading `# Title` heading is optional and ignored by callers.
pub(crate) fn parse_literature_edit_text(text: &str) -> Result<ParsedCard> {
    parse(text, false)
}

fn parse(text: &str, require_title: bool) -> Result<ParsedCard> {
    let lines: Vec<&str> = text.lines().collect();
    let markers: Vec<usize> = lines
        .iter()
        .enumerate()
        .filter_map(|(idx, line)| (line.trim() == REVERSE_MARKER).then_some(idx))
        .collect();
    if markers.len() > 1 {
        bail!("card text must contain at most one {REVERSE_MARKER} line");
    }
    let body_end = markers.first().copied().unwrap_or(lines.len());
    let reverse = markers
        .first()
        .map(|marker| trim_blank_lines(&lines[marker + 1..]).join("\n"))
        .unwrap_or_default();
    let head = &lines[..body_end];
    let first = head.iter().position(|line| !line.trim().is_empty());
    let heading = first.and_then(|idx| title_from_heading(head[idx]).map(|title| (idx, title)));
    let (title, body_start) = match heading {
        Some((idx, title)) => (title, idx + 1),
        None if require_title => {
            bail!("card text must start with a `# Title` heading")
        }
        None => (String::new(), 0),
    };
    if require_title && title.is_empty() {
        bail!("card title cannot be empty");
    }
    Ok(ParsedCard {
        title,
        body: trim_blank_lines(&head[body_start..]).join("\n"),
        reverse,
    })
}

/// The authored identity of one Card (S18, #99): its title, its body and its type fields, hashed.
/// The Reverse section is generated, so it is not authored and not in the hash: writing a reply that
/// links a Card changes that Card's Reverse links without changing this value, so a reader's
/// captured fingerprint stays valid exactly while the authored text does.
pub(crate) fn authored_fingerprint(card: &crate::Card) -> Result<String> {
    let parsed = parse_card_text(&card.text)?;
    let authored = [
        parsed.title,
        parsed.body,
        card.bibtex.clone().unwrap_or_default(),
        card.card_type.id().to_string(),
        card.facet.as_ref().map_or(String::new(), |facet| facet.id().to_string()),
        card.emphasis
            .map_or(String::new(), |emphasis| emphasis.id().to_string()),
        card.level_id().unwrap_or_default().to_string(),
        card.form.map_or(String::new(), |form| form.id().to_string()),
    ];
    let mut hasher = sha2::Sha256::new();
    for field in &authored {
        hasher.update(field.as_bytes());
        hasher.update([0u8]);
    }
    Ok(hasher
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect())
}

/// The exact statement fingerprint of one authored body (§4.5, D087): two Cards whose statements
/// are the same claim get one fingerprint, and no other normalisation happens. Only three things
/// are ignored, exactly as the design says: line endings (CRLF and CR read as LF), the outer
/// whitespace of the statement, and a separately labelled source line (`来源：…`, `出处：…`,
/// `Source: …`), which is evidence beside the claim and not the claim. Formulas, numerical values,
/// signs, variable names, negation, assumptions and scope stay in the text, so a changed sign,
/// value, variable or assumption always gives a different fingerprint, and no formula is renamed
/// or shortened.
pub(crate) fn statement_fingerprint(body: &str) -> String {
    let text = statement_text(body);
    let mut hasher = sha2::Sha256::new();
    hasher.update(text.as_bytes());
    hasher
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// The statement text one fingerprint covers: the body with its line endings normalised, its
/// separately labelled source lines dropped outside fenced code, and its outer whitespace trimmed.
pub(crate) fn statement_text(body: &str) -> String {
    let normalized = body.replace("\r\n", "\n").replace('\r', "\n");
    let mut kept: Vec<&str> = Vec::new();
    let mut fenced = false;
    for line in normalized.split('\n') {
        let trimmed = line.trim();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            fenced = !fenced;
            kept.push(line);
            continue;
        }
        if !fenced && is_source_line(trimmed) {
            continue;
        }
        kept.push(line);
    }
    kept.join("\n").trim().to_string()
}

/// A separately labelled source line: `来源：…`, `出处: …`, or `Source: …`, in either case.
fn is_source_line(trimmed: &str) -> bool {
    let lowered = trimmed.to_lowercase();
    for label in ["来源", "出处", "source"] {
        let Some(rest) = lowered.strip_prefix(label) else {
            continue;
        };
        let rest = rest.trim_start();
        if rest.starts_with('：') || rest.starts_with(':') {
            return true;
        }
    }
    false
}

/// The title of an ATX level-one heading line, such as `# Title` or `# Title #`.
fn title_from_heading(line: &str) -> Option<String> {
    let rest = line
        .strip_prefix("# ")
        .or_else(|| (line == "#").then_some(""))?;
    let rest = rest.trim();
    let rest = rest.trim_end_matches('#');
    Some(if rest.is_empty() || rest.ends_with(' ') {
        rest.trim().to_string()
    } else {
        // A closing `#` run must be preceded by a space; otherwise it is text.
        line[2..].trim().to_string()
    })
}

fn trim_blank_lines<'a>(lines: &'a [&'a str]) -> &'a [&'a str] {
    let start = lines
        .iter()
        .position(|line| !line.trim().is_empty())
        .unwrap_or(lines.len());
    let end = lines
        .iter()
        .rposition(|line| !line.trim().is_empty())
        .map(|idx| idx + 1)
        .unwrap_or(start);
    &lines[start..end.max(start)]
}

/// Exact authored body bytes, excluding title/framing and the generated section.
/// Parsing remains the format validator; this range retains original line ends.
pub(crate) fn authored_body_range(text: &str) -> Result<std::ops::Range<usize>> {
    parse_card_text(text)?;
    let mut heading_end = None;
    let mut marker = text.len();
    let mut offset = 0;
    for line in text.split_inclusive('\n') {
        if line.trim() == REVERSE_MARKER {
            marker = offset;
            break;
        }
        if heading_end.is_none() && !line.trim().is_empty() {
            heading_end = Some(offset + line.len());
        }
        offset += line.len();
    }
    let start = heading_end.unwrap_or(marker);
    let mut first = None;
    let mut last = start;
    offset = start;
    for line in text[start..marker].split_inclusive('\n') {
        let content = line.trim_end_matches(['\r', '\n']);
        if !content.trim().is_empty() {
            first.get_or_insert(offset);
            last = offset + content.len();
        }
        offset += line.len();
    }
    Ok(first.map(|first| first..last).unwrap_or(marker..marker))
}

/// Replace generated bytes only; preserve the authored prefix and marker line.
pub(crate) fn with_reverse_section(text: &str, reverse: &str) -> Result<String> {
    parse_card_text(text)?;
    let mut offset = 0;
    for line in text.split_inclusive('\n') {
        offset += line.len();
        if line.trim() == REVERSE_MARKER {
            let mut out = text[..offset].to_string();
            if !out.ends_with('\n') {
                out.push('\n');
            }
            out.push_str(reverse);
            return Ok(out);
        }
    }
    let mut out = text.to_string();
    if !out.ends_with('\n') {
        out.push('\n');
    }
    if !out.ends_with("\n\n") {
        out.push('\n');
    }
    out.push_str(REVERSE_MARKER);
    out.push('\n');
    out.push_str(reverse);
    Ok(out)
}

pub(crate) fn compose_card_text(title: &str, body: &str, reverse: &str) -> String {
    let mut text = format!("# {title}\n\n");
    if !body.trim().is_empty() {
        text.push_str(body.trim_end_matches(['\n', '\r']));
        text.push_str("\n\n");
    }
    text.push_str(REVERSE_MARKER);
    text.push('\n');
    text.push_str(reverse);
    text
}

/// The generated Reverse link section for the given inbound sources.
pub(crate) fn reverse_section<'a>(sources: impl IntoIterator<Item = (&'a str, &'a str)>) -> String {
    let items = sources
        .into_iter()
        .map(|(address, title)| format!("- [[{address}]] {title}").trim_end().to_string())
        .collect::<Vec<_>>();
    if items.is_empty() {
        String::new()
    } else {
        format!("{REVERSE_HEADING}\n\n{}\n", items.join("\n"))
    }
}

/// The text a new Card opens with: its heading, a blank line, an empty body
/// line to write on, and the Reverse link marker.
pub(crate) fn card_template(title: &str) -> String {
    format!("# {title}\n\n\n{REVERSE_MARKER}\n")
}

pub(crate) fn topic_template(title: &str) -> String {
    card_template(title)
}

pub(crate) fn regular_template() -> String {
    card_template("")
}

/// Convert a Card stored in the pre-Markdown `<--->` format. Returns `None`
/// when the text is not in that format.
pub(crate) fn from_legacy_text(text: &str) -> Option<String> {
    let lines: Vec<&str> = text.lines().collect();
    let delimiters: Vec<usize> = lines
        .iter()
        .enumerate()
        .filter_map(|(idx, line)| (*line == LEGACY_DELIM).then_some(idx))
        .collect();
    let [first, second] = delimiters.as_slice() else {
        return None;
    };
    let title = lines[..*first].join(" ");
    let body = trim_blank_lines(&lines[first + 1..*second]).join("\n");
    Some(compose_card_text(title.trim(), &body, ""))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn compose_and_parse_round_trip_title_body_and_reverse() {
        let text = compose_card_text(
            "Title",
            "first\n\n- item",
            "## Reverse links\n\n- [[0/1]] A\n",
        );
        assert_eq!(
            text,
            "# Title\n\nfirst\n\n- item\n\n<!-- zt:reverse-links -->\n## Reverse links\n\n- [[0/1]] A\n"
        );
        let parsed = parse_card_text(&text).unwrap();
        assert_eq!(parsed.title, "Title");
        assert_eq!(parsed.body, "first\n\n- item");
        assert_eq!(parsed.reverse, "## Reverse links\n\n- [[0/1]] A");
    }

    #[test]
    fn empty_body_and_reverse_compose_to_a_heading_and_marker() {
        assert_eq!(
            compose_card_text("T", "", ""),
            "# T\n\n<!-- zt:reverse-links -->\n"
        );
        let parsed = parse_card_text("# T\n\n<!-- zt:reverse-links -->\n").unwrap();
        assert_eq!((parsed.title.as_str(), parsed.body.as_str()), ("T", ""));
    }

    #[test]
    fn templates_leave_an_empty_body_line_and_parse_to_canonical_text() {
        assert_eq!(regular_template(), "# \n\n\n<!-- zt:reverse-links -->\n");
        let parsed = parse_card_text(&topic_template("T")).unwrap();
        assert_eq!(
            compose_card_text(&parsed.title, &parsed.body, ""),
            compose_card_text("T", "", "")
        );
    }

    #[test]
    fn marker_is_optional_but_unique() {
        let parsed = parse_card_text("# T\nbody line\n").unwrap();
        assert_eq!(parsed.body, "body line");
        assert_eq!(parsed.reverse, "");
        let error =
            parse_card_text(&format!("# T\n{REVERSE_MARKER}\n{REVERSE_MARKER}\n")).unwrap_err();
        assert_eq!(
            error.to_string(),
            "card text must contain at most one <!-- zt:reverse-links --> line"
        );
    }

    #[test]
    fn regular_cards_require_a_nonempty_level_one_heading() {
        for (text, expected) in [
            (
                "no heading\n",
                "card text must start with a `# Title` heading",
            ),
            (
                "## Second level\n",
                "card text must start with a `# Title` heading",
            ),
            ("#Title\n", "card text must start with a `# Title` heading"),
            ("# \n\nbody\n", "card title cannot be empty"),
            ("", "card text must start with a `# Title` heading"),
        ] {
            assert_eq!(parse_card_text(text).unwrap_err().to_string(), expected);
        }
        assert_eq!(parse_card_text("\n\n# Late  \nx").unwrap().title, "Late");
        assert_eq!(parse_card_text("# Closed #\n").unwrap().title, "Closed");
        assert_eq!(parse_card_text("# C#\n").unwrap().title, "C#");
    }

    #[test]
    fn literature_edit_text_may_omit_the_heading() {
        let parsed = parse_literature_edit_text("just notes\n").unwrap();
        assert_eq!(
            (parsed.title.as_str(), parsed.body.as_str()),
            ("", "just notes")
        );
        let parsed = parse_literature_edit_text("# Anything\nnotes").unwrap();
        assert_eq!(parsed.body, "notes");
    }

    #[test]
    fn reverse_sections_are_markdown_lists_under_a_heading() {
        assert_eq!(reverse_section([]), "");
        assert_eq!(
            reverse_section([("0/0", "Earlier"), ("0/2", "")]),
            "## Reverse links\n\n- [[0/0]] Earlier\n- [[0/2]]\n"
        );
    }

    #[test]
    fn the_statement_fingerprint_ignores_only_line_endings_outer_whitespace_and_source_lines() {
        let body = "当策略互补时，同一经济有两个均衡：$x_i=\\arg\\max_x u_i(x,x_{-i})$。\n\n假设：策略互补、参与者对称。\n\n来源：[[K]] §2.1";
        let fingerprint = statement_fingerprint(body);
        // The same statement written with CRLF, outer blank lines, another source line and its
        // place: the same claim, so one fingerprint.
        let crlf = "\n\n当策略互补时，同一经济有两个均衡：$x_i=\\arg\\max_x u_i(x,x_{-i})$。\r\n\r\n假设：策略互补、参与者对称。\r\n\r\nSource: [[K]] §9\r\n  ";
        assert_eq!(statement_fingerprint(crlf), fingerprint);
        assert_eq!(statement_fingerprint(body.trim()), fingerprint);
        // Formulas, values, signs, variables, negation, assumptions and scope stay in the text.
        for changed in [
            "当策略互补时，同一经济有两个均衡：$x_i=-\\arg\\max_x u_i(x,x_{-i})$。\n\n假设：策略互补、参与者对称。\n\n来源：[[K]] §2.1",
            "当策略互补时，同一经济有两个均衡：$x_j=\\arg\\max_x u_i(x,x_{-i})$。\n\n假设：策略互补、参与者对称。\n\n来源：[[K]] §2.1",
            "当策略互补时，同一经济有两个均衡：$x_i=\\arg\\max_x u_i(x,x_{-i})$。\n\n假设：策略互补。\n\n来源：[[K]] §2.1",
            "当策略互补时，同一经济没有两个均衡。\n\n假设：策略互补、参与者对称。\n\n来源：[[K]] §2.1",
            "当策略互补时，同一经济有三个均衡。\n\n假设：策略互补、参与者对称。\n\n来源：[[K]] §2.1",
        ] {
            assert_ne!(statement_fingerprint(changed), fingerprint, "{changed}");
        }
        // A source line inside a code fence is code, not a separately labelled source line.
        let fenced = "陈述。\n\n```\n来源：[[K]]\n```\n";
        assert!(statement_fingerprint(fenced) != statement_fingerprint("陈述。\n\n```\n```\n"));
        // An entry that states no body has one stable fingerprint.
        assert_eq!(statement_fingerprint(""), statement_fingerprint("\n\n  \r\n"));
    }

    #[test]
    fn legacy_text_converts_title_and_body_and_drops_the_reverse_section() {
        assert_eq!(
            from_legacy_text(
                "Title\n<--->\nbody\n<--->\nThis note has been referred by note [[0/1]] X"
            )
            .as_deref(),
            Some("# Title\n\nbody\n\n<!-- zt:reverse-links -->\n")
        );
        assert_eq!(from_legacy_text("# Title\n\nbody\n"), None);
    }
}
